"""Package the verified Kotlin delivery as a buildless listening page."""
import argparse, hashlib, json, pathlib, shutil, wave, zipfile
p=argparse.ArgumentParser();p.add_argument('delivery',type=pathlib.Path);p.add_argument('output',type=pathlib.Path);a=p.parse_args()
m=json.loads((a.delivery/'manifest.json').read_text());assert len(m['kits'])==3
out=a.output;out.mkdir(parents=True,exist_ok=True);shutil.copytree(a.delivery/'audio',out/'audio',dirs_exist_ok=True)
for name,digest in m['audioSha256'].items():
    f=out/'audio'/name
    assert hashlib.sha256(f.read_bytes()).hexdigest()==digest
    with wave.open(str(f)) as w: assert w.getframerate()==44100 and w.getnchannels() in (1,2) and w.getnframes()>0
for k in m['kits']:
    assert k['gridCells']==162 and len(k['pads'])==18
    for name in k['downloads'].values():
        src=a.delivery/name;assert src.stat().st_size<25*1024*1024
        with zipfile.ZipFile(src) as z: assert z.testzip() is None
        shutil.copy2(src,out/name)
shutil.copy2(a.delivery/'manifest.json',out/'manifest.json')
(out/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spore · Synthetic Jungle Kits</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#101914;color:#f1f4e9}*{box-sizing:border-box}body{max-width:1100px;margin:auto;padding:24px 20px 80px}a{color:#c8f783}header{padding:38px 0 24px}h1{font-size:clamp(2.8rem,8vw,5.8rem);line-height:.98;letter-spacing:-.055em;margin:18px 0 26px}h2{font-size:1.7rem}p{line-height:1.6;max-width:780px}.eyebrow{font-size:.8rem;letter-spacing:.18em;color:#c8f783}.muted,small{color:#acbcae}.player{position:sticky;top:0;background:#101914f5;border-block:1px solid #425940;padding:12px 0;z-index:2}.player audio{width:100%}.player p{margin:5px 0 10px}.player button{float:right;padding:8px 18px}section{padding:28px 0;border-bottom:1px solid #354835}button{font:inherit;color:inherit;background:#203426;border:1px solid #58724f;padding:15px;border-radius:8px;cursor:pointer;text-align:left}button:hover,button:focus-visible{background:#385035;outline:2px solid #c8f783}button.primary{background:#c8f783;color:#142017;font-weight:750}.row{display:flex;gap:12px;flex-wrap:wrap}.row button{flex:1;min-width:220px}.pads{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px;margin:18px 0}.pads button{min-height:80px}.pads small{display:block;margin-bottom:6px}details{margin-top:20px}summary{cursor:pointer;padding:12px 0}.downloads a{display:inline-block;padding:10px 14px;border:1px solid #58724f;border-radius:6px;margin:4px 8px 4px 0}#error{color:#ffb9aa}footer{margin-top:25px;font-size:.9rem}.badge{font-size:.8rem;color:#c8f783;font-weight:400;margin-left:12px}@media(max-width:480px){body{padding-inline:14px}.pads{grid-template-columns:repeat(2,minmax(0,1fr))}.badge{display:block;margin:8px 0}}
</style></head><body><a href="../">← Spore Station</a><header><div class="eyebrow">SAMPLE-FREE DRUMS · THREE GENRE KITS</div><h1>Dry roots.<br>Orbital branches.</h1><p>The approved kick and snare now anchor a complete Jungle kit. Dub and broken-beat variations add different voicings, patterns and psychedelic accents. Start with Dry Jungle, then open the pads to judge each new voice.</p><p class="muted">18 pads per kit · 3 velocity layers × 3 takes · authored roll and riser</p></header>
<div class="player"><button id="stop">Stop</button><p id="now" aria-live="polite">Choose a groove or pad.</p><audio id="audio" controls preload="none"></audio><p id="error" role="alert"></p></div><main id="kits"></main>
<section><h2>Ready for the sampler</h2><p>Each download contains one complete kit in the selected format. Native, SFZ and MPC 3 retain all 162 velocity/take cells. MPC 3 includes the four-bar audition pattern; no MPC 2 fallback is included.</p><p class="muted">Grooves use the kit's pad mixer levels, with a single gain adjustment for preview headroom. Pad solos use raw source gain. Touch clips play the saved kick and snare through all three levels and three repeats.</p></section>
<details><summary>What is approved, and what is verified?</summary><p>The core kick and snare were approved in the previous audition. Jungle pads 1 and 3 preserve those sources. The expanded voices, genre arrangements and gestures are new and awaiting your listening verdict.</p><p>All 486 cells pass source replay, native save/load and playback, SFZ import/playback and MPC 3 grid/PCM read-back. Open and closed hats share a choke group. The core ports pass 34 Python waveform comparisons. These are software checks; Android and physical MPC playback remain unverified.</p><p>The sources use procedural oscillators, filtered noise, SKIN, ONSET and TINES. No reference recordings are loaded. Effects live on the colour accents; the Jungle kick and snare stay dry. Source recipes replay through Kotlin but are not editable patches in the app synth picker.</p><p><a href="manifest.json">Delivery manifest and audio hashes</a> · <a href="design.md">Design and acceptance ledger</a> · <a href="../approved-core/">Previous core audition</a></p></details><footer class="muted">Spore Station · 14 November 2026 · Owner-private audition</footer>
<script>
const audio=document.getElementById('audio'),now=document.getElementById('now'),error=document.getElementById('error');let request=0;
function stop(){request++;audio.pause();audio.currentTime=0;now.textContent='Stopped.'}
document.getElementById('stop').onclick=stop;
audio.onerror=()=>{error.textContent='Audio could not load. Try another clip or reload.'};
function play(file,title){stop();const id=request;error.textContent='';audio.src='audio/'+file;now.textContent=title;audio.play().catch(()=>{if(request===id)error.textContent='Press play in the audio controls to start playback.'})}
function button(file,title,primary=false){const b=document.createElement('button');b.textContent=title;if(primary)b.className='primary';b.onclick=()=>play(file,title);return b}
fetch('manifest.json').then(r=>{if(!r.ok)throw Error('manifest');return r.json()}).then(m=>{for(const k of m.kits){const s=document.createElement('section'),h=document.createElement('h2');h.textContent=k.title;const badge=document.createElement('span');badge.className='badge';badge.textContent=k.bpm+' BPM';h.append(badge);s.append(h);const row=document.createElement('div');row.className='row';row.append(button(k.id+'-groove.wav','Play '+k.title,true),button(k.id+'-touch.wav','Kick + snare · touch and repeats'));s.append(row);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Audition all 18 pads · including roll and riser';details.append(summary);const pads=document.createElement('div');pads.className='pads';for(const p of k.pads){const b=button(k.id+'-pad-'+p.slot+'.wav',p.name);const n=document.createElement('small');n.textContent=String(p.slot).padStart(2,'0');b.prepend(n);pads.append(b)}details.append(pads);s.append(details);const downloads=document.createElement('div');downloads.className='downloads';for(const [format,file]of Object.entries(k.downloads)){const a=document.createElement('a');a.href=file;a.download='';a.textContent='Download '+format;downloads.append(a)}s.append(downloads);document.getElementById('kits').append(s)}}).catch(()=>{error.textContent='The kit list could not load. Please reload.'});
</script></body></html>''')
print(f'Validated and packaged {len(m["audioSha256"])} WAVs and 9 archives in {out}')
